package in.rekhaastrology.oracleinbox;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.Color;import android.net.Uri;import android.os.*;import android.provider.MediaStore;import android.view.*;import android.webkit.*;import android.widget.*;import java.io.*;import java.net.URL;import java.util.UUID;import java.util.concurrent.*;import javax.net.ssl.HttpsURLConnection;
public class MainActivity extends Activity {
 static final String HOST="rekhaastrology.in",BASE="/manual-inbox/",HOME="https://"+HOST+BASE;
 private WebView web;private FrameLayout root;private ValueCallback<Uri[]> chooser;private PermissionRequest pendingMic;private long lastTouch;private Uri capture;private String saveUrl;private View fullscreen;private WebChromeClient.CustomViewCallback fullCallback;private final ExecutorService io=Executors.newSingleThreadExecutor();
 private boolean origin(String value){if(value==null)return false;Uri u=Uri.parse(value);return "https".equals(u.getScheme())&&HOST.equals(u.getHost())&&(u.getPort()==-1||u.getPort()==443);}
 private boolean trusted(String value){return origin(value)&&Uri.parse(value).getPath().startsWith(BASE);}
 @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().setStatusBarColor(Color.rgb(0,128,105));getWindow().setNavigationBarColor(Color.WHITE);root=new FrameLayout(this);setContentView(root);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});web=new WebView(this);root.addView(web,new FrameLayout.LayoutParams(-1,-1));WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(true);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setSafeBrowsingEnabled(true);s.setMediaPlaybackRequiresUserGesture(true);s.setUserAgentString(s.getUserAgentString()+" RekhaInboxAndroid/1.0.0");CookieManager.getInstance().setAcceptCookie(true);CookieManager.getInstance().setAcceptThirdPartyCookies(web,false);WebView.setWebContentsDebuggingEnabled(false);
  web.setWebViewClient(new WebViewClient(){
   @Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest r){Uri u=r.getUrl();if(trusted(u.toString()))return false;if(r.isForMainFrame()&&"https".equals(u.getScheme()))try{startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(Exception ignored){}return true;}
   @Override public void onPageStarted(WebView v,String url,android.graphics.Bitmap b){if(pendingMic!=null){pendingMic.deny();pendingMic=null;}}
   @Override public void onPageFinished(WebView v,String u){CookieManager.getInstance().flush();}
   @Override public void onReceivedSslError(WebView v,SslErrorHandler handler,android.net.http.SslError e){handler.cancel();Toast.makeText(MainActivity.this,"Secure connection failed. Check your connection and phone date.",Toast.LENGTH_LONG).show();}
   @Override public void onReceivedError(WebView v,WebResourceRequest r,WebResourceError e){if(r.isForMainFrame())new AlertDialog.Builder(MainActivity.this).setTitle("Connection unavailable").setMessage("Check your internet connection, then try again.").setPositiveButton("Retry",(d,w)->web.loadUrl(HOME)).setNegativeButton("Close",(d,w)->finish()).show();}
  });
  web.setWebChromeClient(new WebChromeClient(){
   @Override public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> callback,FileChooserParams p){if(!trusted(web.getUrl()))return false;if(chooser!=null)chooser.onReceiveValue(null);chooser=callback;
    if(p.isCaptureEnabled()){try{capture=Uri.parse("content://in.rekhaastrology.oracleinbox.photo/capture-"+UUID.randomUUID()+".jpg");Intent camera=new Intent(MediaStore.ACTION_IMAGE_CAPTURE);camera.putExtra(MediaStore.EXTRA_OUTPUT,capture);camera.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);camera.setClipData(ClipData.newRawUri("photo",capture));startActivityForResult(camera,52);return true;}catch(Exception ignored){capture=null;}}
    Intent picker=new Intent(Intent.ACTION_OPEN_DOCUMENT);picker.addCategory(Intent.CATEGORY_OPENABLE);picker.setType("*/*");String[] types=p.getAcceptTypes();if(types.length>0&&types[0].contains("/"))picker.putExtra(Intent.EXTRA_MIME_TYPES,types);picker.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,p.getMode()==FileChooserParams.MODE_OPEN_MULTIPLE);try{startActivityForResult(picker,51);}catch(Exception e){chooser.onReceiveValue(null);chooser=null;}return true;}
   @Override public void onPermissionRequest(PermissionRequest r){runOnUiThread(()->{String[] resources=r.getResources();if(!origin(r.getOrigin().toString())||!trusted(web.getUrl())||resources.length!=1||!PermissionRequest.RESOURCE_AUDIO_CAPTURE.equals(resources[0])||pendingMic!=null||SystemClock.elapsedRealtime()-lastTouch>60000){r.deny();return;}pendingMic=r;if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)==PackageManager.PERMISSION_GRANTED)grantMic();else requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},50);});}
   @Override public void onPermissionRequestCanceled(PermissionRequest r){if(pendingMic==r)pendingMic=null;}
   @Override public void onShowCustomView(View view,CustomViewCallback cb){if(fullscreen!=null){cb.onCustomViewHidden();return;}fullscreen=view;fullCallback=cb;web.setVisibility(View.GONE);root.addView(view,new FrameLayout.LayoutParams(-1,-1));}
   @Override public void onHideCustomView(){hideVideo();}
  });
  web.setDownloadListener((url,agent,disposition,mime,length)->download(url,mime));web.loadUrl(HOME);
 }
 private void grantMic(){PermissionRequest r=pendingMic;pendingMic=null;if(r==null)return;if(trusted(web.getUrl())&&origin(r.getOrigin().toString())&&checkSelfPermission(Manifest.permission.RECORD_AUDIO)==PackageManager.PERMISSION_GRANTED)r.grant(new String[]{PermissionRequest.RESOURCE_AUDIO_CAPTURE});else r.deny();}
 @Override public void onUserInteraction(){super.onUserInteraction();lastTouch=SystemClock.elapsedRealtime();}
 @Override public void onRequestPermissionsResult(int code,String[] p,int[] result){super.onRequestPermissionsResult(code,p,result);if(code==50)grantMic();}
 private void download(String url,String mime){if(!trusted(url)||!Uri.parse(url).getPath().equals(BASE+"api/media")){if(trusted(url)&&url.endsWith(".apk"))try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(Exception ignored){}return;}saveUrl=url;Intent choose=new Intent(Intent.ACTION_CREATE_DOCUMENT);choose.addCategory(Intent.CATEGORY_OPENABLE);choose.setType(mime==null?"application/octet-stream":mime);choose.putExtra(Intent.EXTRA_TITLE,"Rekha-attachment");try{startActivityForResult(choose,53);}catch(Exception ignored){saveUrl=null;}}
 @Override protected void onActivityResult(int code,int result,Intent data){super.onActivityResult(code,result,data);if((code==51||code==52)&&chooser!=null){Uri[] values=result==RESULT_OK?(code==52&&capture!=null?new Uri[]{capture}:WebChromeClient.FileChooserParams.parseResult(result,data)):null;chooser.onReceiveValue(values);chooser=null;capture=null;}if(code==53&&result==RESULT_OK&&data!=null&&saveUrl!=null){final String url=saveUrl,cookie=CookieManager.getInstance().getCookie(url);final Uri target=data.getData();saveUrl=null;io.execute(()->{HttpsURLConnection c=null;try{c=(HttpsURLConnection)new URL(url).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(15000);c.setReadTimeout(60000);if(cookie!=null)c.setRequestProperty("Cookie",cookie);if(c.getResponseCode()!=200)throw new IOException();try(InputStream in=c.getInputStream();OutputStream out=getContentResolver().openOutputStream(target)){byte[] b=new byte[32768];int n;long total=0;while((n=in.read(b))!=-1){total+=n;if(total>100L*1024*1024)throw new IOException();out.write(b,0,n);}}runOnUiThread(()->Toast.makeText(this,"Attachment saved",Toast.LENGTH_SHORT).show());}catch(Exception e){runOnUiThread(()->Toast.makeText(this,"Could not save. Sign in and try again.",Toast.LENGTH_LONG).show());}finally{if(c!=null)c.disconnect();}});}}
 private void hideVideo(){if(fullscreen!=null){root.removeView(fullscreen);fullscreen=null;web.setVisibility(View.VISIBLE);fullCallback.onCustomViewHidden();fullCallback=null;}}
 @Override public void onBackPressed(){if(fullscreen!=null)hideVideo();else web.evaluateJavascript("document.getElementById('app')?.classList.contains('open')",result->{if("true".equals(result))web.evaluateJavascript("document.getElementById('back').click()",null);else if(web.canGoBack())web.goBack();else finish();});}
 @Override protected void onPause(){CookieManager.getInstance().flush();super.onPause();}
 @Override protected void onDestroy(){if(pendingMic!=null)pendingMic.deny();if(chooser!=null)chooser.onReceiveValue(null);io.shutdownNow();web.destroy();super.onDestroy();}
}
